  "test": "import os
import pytest
from opentelemetry.exporter.otlp.proto.http.trace_exporter import Compression
from langfuse._client.span_processor import LangfuseSpanProcessor


def test_get_compression_returns_configured_value(monkeypatch):
    # Ensure env vars do not interfere
    monkeypatch.delenv('LANGFUSE_OTEL_COMPRESSION', raising=False)
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://localhost",
        otel_compression="none",
        span_exporter=None,
    )
    try:
        assert processor.get_compression() == Compression.NoCompression
    finally:
        processor.shutdown()


def test_get_compression_returns_none_for_custom_exporter(monkeypatch):
    class DummyExporter:
        def export(self, spans):
            pass
        def shutdown(self):
            pass

    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://localhost",
        span_exporter=DummyExporter(),
    )
    try:
        assert processor.get_compression() is None
    finally:
        processor.shutdown()
"
